23	HcclResult HcclAllReduce(
24	    void* sendBuf, void* recvBuf, uint64_t count, HcclDataType dataType, HcclReduceOp op, HcclComm comm,
25	    aclrtStream stream)
26	{
27	    HCCL_INFO("Start to run execute HcclAllReduce");
28	    if (GetHcommVersion() < CANN_VERSION(9, 0, 0)) { // compat handle
29	        return HcclAllReduceInner(sendBuf, recvBuf, count, dataType, op, comm, stream);
30	    }
31	
32	    bool isOutPlace = false;
33	    CHK_RET(IsOutPlaceDevice(isOutPlace));
34	    if (!isOutPlace) {
35	        return HcclAllReduceInner(sendBuf, recvBuf, count, dataType, op, comm, stream);
36	    }
37	    CHK_PRT_RET(count == 0, HCCL_WARNING("input count is 0, return all reduce success"), HCCL_SUCCESS);
38	
39	    HcclUs startut = TIME_NOW(); // 走老流程的判断时间不统计在内
40	    OpParam param;
41	    CHK_RET(AllReduceInitAndCheck(comm, sendBuf, recvBuf, count, dataType, op, stream, param));
42	
43	    /* 接口交互信息日志 */
44	    CHK_RET(AllReduceEntryLog(sendBuf, recvBuf, count, dataType, op, stream, param.tag, "HcclAllReduce"));
45	
46	    // 执行AllReduce
47	    CHK_RET_AND_PRINT_IDE(AllReduceOutPlace(sendBuf, recvBuf, count, dataType, op, comm, stream, param), param.tag);
48	
49	    CHK_RET(LogHcclExit("HcclAllReduce", param.tag, startut));
50	
51	    return HCCL_SUCCESS;
52	}
