54	HcclResult HcclAllReduceGraphMode(
55	    void* sendBuf, void* recvBuf, uint64_t sendCount, HcclDataType dataType, HcclReduceOp op, const char* group,
56	    aclrtStream stream, const char* tag, void** streams, size_t streamCount, void* scratchMemAddr,
57	    uint64_t scratchMemSize)
58	{
59	    HCCL_INFO("Start to run execute HcclAllReduceGraphMode");
60	    // 根据group获取通信域
61	    CHK_PTR_NULL(group);
62	    HcclComm comm = nullptr;
63	    HCCL_INFO("[HcclAllReduceGraphMode] get group name: %s", group);
64	    CHK_RET(HcomGetCommHandleByGroup(group, &comm));
65	    CHK_PRT_RET(sendCount == 0, HCCL_WARNING("input sendCount is 0, return all reduce success"), HCCL_SUCCESS);
66	
67	    HcclUs startut = TIME_NOW(); // 走老流程的判断时间不统计在内
68	    OpParam param;
69	    CHK_RET(AllReduceInitAndCheck(comm, sendBuf, recvBuf, sendCount, dataType, op, stream, param));
70	
71	    // 检查tag有效性
72	    CHK_RET(HcclCheckTag(tag));
73	    int ret = sprintf_s(param.tag, sizeof(param.tag), "%s", tag);
74	    CHK_PRT_RET((ret <= 0), HCCL_ERROR("failed to fill param.tag"), HCCL_E_INTERNAL);
75	
76	    // 拼装ResPackGraphMode
77	    ResPackGraphMode resPack;
78	    // 设置tag
79	    if (strncpy_s(resPack.tag, sizeof(resPack.tag), tag, sizeof(resPack.tag) - 1) != 0) {
80	        HCCL_ERROR("failed to fill resPack.tag");
81	        return HCCL_E_INTERNAL;
82	    }
83	    // 设置streams
84	    if (streams != nullptr && streamCount > 0) {
85	        for (size_t i = 0; i < streamCount; i++) {
86	            resPack.streams.push_back(static_cast<aclrtStream>(streams[i]));
87	        }
88	    }
89	    // 设置scratchMem
90	    resPack.scratchMemAddr = scratchMemAddr;
91	    resPack.scratchMemSize = scratchMemSize;
92	    std::string tagStr = tag;
93	
94	    /* 接口交互信息日志 */
95	    CHK_RET(AllReduceEntryLog(
96	        sendBuf, recvBuf, sendCount, dataType, op, stream, param.tag, "HcclAllReduceGraphMode", true));
97	    // 执行AllReduce
98	    CHK_RET_AND_PRINT_IDE(
99	        AllReduceOutPlaceGraphMode(sendBuf, recvBuf, sendCount, dataType, op, comm, stream, resPack, param),
100	        tagStr.c_str());
101	    CHK_RET(LogHcclExit("HcclAllReduceGraphMode", param.tag, startut, true));
102	
103	    return HCCL_SUCCESS;
104	}
