107	HcclResult AllReduceInitAndCheck(
108	    HcclComm comm, void* sendBuf, void* recvBuf, uint64_t count, HcclDataType dataType, HcclReduceOp op,
109	    const aclrtStream stream, OpParam& param)
110	{
111	    // 入口的地方先解析环境变量，在初始化环境变量的时候需要设置为AICPU展开
112	    CHK_RET(InitEnvConfig());
113	
114	    // 参数校验等工作
115	    CHK_RET(CheckAllReduceInputPara(comm, sendBuf, recvBuf, stream));
116	    u32 rankSize = INVALID_VALUE_RANKSIZE;
117	    CHK_RET(HcclGetRankSize(comm, &rankSize));
118	    u32 userRank = INVALID_VALUE_RANKID;
119	    CHK_RET(HcclGetRankId(comm, &userRank));
120	    CHK_RET(HcclGetCommName(comm, param.commName));
121	
122	    // topoInfo的tag，所有相同的算子可以共享
123	    int ret = sprintf_s(param.tag, sizeof(param.tag), "AllReduce_%s", param.commName);
124	    CHK_PRT_RET((ret <= 0), "failed to fill param.tag", HCCL_E_INTERNAL);
125	
126	    CHK_RET(HcclCheckTag(param.tag));
127	    CHK_RET_AND_PRINT_IDE(HcomCheckUserRank(rankSize, userRank), param.tag);
128	    CHK_RET(CheckCount(count));
129	    CHK_RET(CheckDataType(dataType, true));
130	    CHK_RET(CheckReduceOp(dataType, op));
131	
132	    return HCCL_SUCCESS;
133	}
