159	HcclResult FillAllReduceOpParam(
160	    void* sendBuf, void* recvBuf, uint64_t count, HcclDataType dataType, HcclReduceOp op, const HcclComm comm,
161	    aclrtStream stream, OpMode opMode, OpParam& param)
162	{
163	    (void)comm;
164	    u32 perDataSize = DATATYPE_SIZE_TABLE[dataType];
165	    u64 outputSize = count * perDataSize;
166	    u64 inputSize = outputSize;
167	
168	    param.stream = stream;
169	    param.reduceType = op;
170	    param.opMode = opMode;
171	
172	    HcclDevType deviceType = HcclDevType::DEV_TYPE_COUNT;
173	    CHK_RET(HcclGetDeviceType(deviceType));
174	
175	    // 参数准备
176	    param.inputPtr = sendBuf;
177	    param.inputSize = inputSize;
178	    param.outputPtr = recvBuf;
179	    param.outputSize = outputSize;
180	    param.DataDes.count = count;
181	    param.DataDes.dataType = dataType;
182	    param.opType = HcclCMDType::HCCL_CMD_ALLREDUCE;
183	    param.enableDetour = false;
184	    param.deviceType = deviceType;
185	    param.reduceType = op;
186	    return HCCL_SUCCESS;
187	}
