189	HcclResult AllReduceOutPlaceCommon(
190	    void* sendBuf, void* recvBuf, uint64_t count, HcclDataType dataType, HcclReduceOp op, HcclComm comm,
191	    aclrtStream stream, OpMode opMode, const ResPackGraphMode& resPack, OpParam& param)
192	{
193	    HCCL_INFO("Start to execute AllReduceOutPlace");
194	
195	    CHK_RET(FillAllReduceOpParam(sendBuf, recvBuf, count, dataType, op, comm, stream, opMode, param));
196	
197	    CHK_RET(HcclGetOpExpansionMode(comm, param));
198	
199	    // 9.0.0 ccu模式走老流程
200	    if (opMode == OpMode::OPBASE && GetHcommVersion() == CANN_VERSION(9, 0, 0)
201	        && param.engine == CommEngine::COMM_ENGINE_CCU) {
202	        return HcclAllReduceInner(sendBuf, recvBuf, count, dataType, op, comm, stream);
203	    }
204	
205	    CcuFastLaunchCtx* ccuFastLaunchCtx = nullptr;
206	    if ((opMode == OpMode::OPBASE) && ShouldGoCcuFastLaunch(comm, param, &ccuFastLaunchCtx)) {
207	        return HcclExecOpCcuFastLaunch(comm, param, ccuFastLaunchCtx);
208	    }
209	
210	    if (param.engine == CommEngine::COMM_ENGINE_AIV) {
211	        bool aivCacheHit = false;
212	        CHK_RET(HcclAivCacheCheckAndReplay(comm, param, aivCacheHit));
213	        if (aivCacheHit) {
214	            return HCCL_SUCCESS;
215	        }
216	    }
217	
218	    // 单卡校验
219	    u32 userRankSize;
220	    CHK_RET(HcclGetRankSize(comm, &userRankSize));
221	    if (userRankSize == 1) {
222	        HCCL_WARNING("[%s] ranksize == 1, enter SingleRankProc", __func__);
223	        CHK_RET(SingleRankProc(comm, param));
224	        return HcclResult::HCCL_SUCCESS;
225	    }
226	
227	    std::string algName;
228	    std::unique_ptr<TopoInfoWithNetLayerDetails> topoInfo = std::make_unique<TopoInfoWithNetLayerDetails>();
229	    CHK_RET(Selector(comm, param, topoInfo, algName));
230	
231	    CHK_RET(HcclExecOp(comm, param, topoInfo, algName, resPack));
232	    HCCL_INFO("Execute AllReduceOutPlace success.");
233	    return HCCL_SUCCESS;
234	}
235	
236	HcclResult AllReduceEntryLog(
237	    void* sendBuf, void* recvBuf, uint64_t count, HcclDataType dataType, HcclReduceOp op, aclrtStream stream,
238	    const char* tag, const std::string& opName, bool forceLog)
239	{
240	    if (forceLog || GetExternalInputHcclEnableEntryLog()) {
241	        s32 deviceId = 0;
242	        ACLCHECK(aclrtGetDevice(&deviceId));
243	        s32 streamId = 0;
244	        ACLCHECK(aclrtStreamGetId(stream, &streamId));
245	        char stackLogBuffer[LOG_TMPBUF_SIZE];
246	        s32 ret = snprintf_s(
247	            stackLogBuffer, LOG_TMPBUF_SIZE, LOG_TMPBUF_SIZE - 1U,
248	            "tag[%s], sendBuf[%p], recvBuf[%p], count[%llu], dataType[%s], reduceOp[%s], streamId[%d], deviceId[%d]",
249	            tag, sendBuf, recvBuf, count, GetDataTypeEnumStr(dataType).c_str(), GetReduceOpEnumStr(op).c_str(),
250	            streamId, deviceId);
251	
252	        CHK_PRT_CONT(ret == -1, HCCL_WARNING("Failed to build log info, tag[%s].", tag));
253	        std::string logInfo = "Entry-" + opName + ":" + std::string(stackLogBuffer);
254	        HCCL_RUN_INFO("%s", logInfo.c_str());
255	    }
256	    return HCCL_SUCCESS;
257	}
258	
259	HcclResult AllReduceOutPlaceGraphMode(
260	    void* sendBuf, void* recvBuf, uint64_t count, HcclDataType dataType, HcclReduceOp op, HcclComm comm,
261	    aclrtStream stream, const ResPackGraphMode& resPack, OpParam& param)
262	{
263	    HCCL_INFO("Start to execute AllReduceOutPlaceGraphMode");
264	    CHK_RET(
265	        AllReduceOutPlaceCommon(sendBuf, recvBuf, count, dataType, op, comm, stream, OpMode::OFFLOAD, resPack, param));
266	    HCCL_INFO("Execute AllReduceOutPlaceGraphMode success.");
267	    return HCCL_SUCCESS;
268	}
269	
270	HcclResult AllReduceOutPlace(
271	    void* sendBuf, void* recvBuf, uint64_t count, HcclDataType dataType, HcclReduceOp op, HcclComm comm,
272	    aclrtStream stream, OpParam& param)
273	{
274	    HCCL_INFO("Start to execute AllReduceOutPlace");
275	    CHK_RET(AllReduceOutPlaceCommon(
276	        sendBuf, recvBuf, count, dataType, op, comm, stream, OpMode::OPBASE, ResPackGraphMode(), param));
277	    HCCL_INFO("Execute AllReduceOutPlace success.");
278	    return HCCL_SUCCESS;
279	}
