290	bool ShouldGoCcuFastLaunch(HcclComm comm, OpParam& param, CcuFastLaunchCtx** ccuFastLaunchCtx)
291	{
292	#if CANN_VERSION_NUM >= CANN_VERSION(9, 1, 0)
293	    param.hcclComm = comm;
294	    if (param.opMode == OpMode::OFFLOAD) {
295	        return false;
296	    }
297	    // 1. 引擎为ccu模式
298	    if (param.engine != CommEngine::COMM_ENGINE_CCU) {
299	        return false;
300	    }
301	    if (SetOpParamFastLaunchTag(param) != HCCL_SUCCESS) {
302	        return false;
303	    }
304	
305	    // 2. 查到engineCtx
306	    uint64_t size = 0;
307	    void* fastLaunchCtxPtr = nullptr;
308	    if (HcclEngineCtxGet(comm, param.fastLaunchTag, CommEngine::COMM_ENGINE_CCU, &fastLaunchCtxPtr, &size)
309	        == HCCL_SUCCESS) {
310	        HCCL_INFO("[ShouldGoCcuFastLaunch] get fastLaunchCtx success, size is %u", size);
311	        *ccuFastLaunchCtx = reinterpret_cast<CcuFastLaunchCtx*>(fastLaunchCtxPtr);
312	        return true;
313	    }
314	    return false;
315	#else
316	    (void)comm;
317	    (void)param;
318	    (void)ccuFastLaunchCtx;
319	    return false;
320	#endif
321	}
