323	HcclResult ConstructHcclDfxOpInfo(
324	    const OpParam& param, const char* tag, u32 tagSize, HcclDfxOpInfoCompat& hcclDfxOpInfo, ThreadHandle cpuTsThread)
325	{
326	    bool isAclGraph = IsStreamInCaptureMode(param.stream);
327	    hcclDfxOpInfo.opMode = isAclGraph ? static_cast<u32>(ops_hccl::OpMode::ACLGRAPH) : static_cast<u32>(param.opMode);
328	    hcclDfxOpInfo.opType = static_cast<u32>(param.opType);
329	    hcclDfxOpInfo.reduceOp = static_cast<u32>(param.reduceType);
330	    CHK_RET(GetHcclDfxOpInfoDataType(param, hcclDfxOpInfo.dataType));
331	
332	    // rankSize获取指定算子的dataCount
333	    u32 userRankSize{0};
334	    CHK_RET(HcclGetRankSize(param.hcclComm, &userRankSize));
335	    CHK_RET(GetHcclDfxOpInfoDataCount(param, userRankSize, hcclDfxOpInfo.dataCount));
336	    hcclDfxOpInfo.root = param.root;
337	    hcclDfxOpInfo.engine = param.engine;
338	
339	    hcclDfxOpInfo.inputMemAddr = reinterpret_cast<uint64_t>(param.inputPtr);
340	    hcclDfxOpInfo.inputMemSize = param.inputSize;
341	    hcclDfxOpInfo.outputMemAddr = reinterpret_cast<uint64_t>(param.outputPtr);
342	    hcclDfxOpInfo.outputMemSize = param.outputSize;
343	
344	    hcclDfxOpInfo.cpuTsThread = cpuTsThread;
345	    hcclDfxOpInfo.cpuWaitAicpuNotifyIdx = HOST_WAIT_AICPU_NOTIFYIDX;
346	    s32 sRet = strncpy_s(hcclDfxOpInfo.algTag, ALG_TAG_LENGTH, tag, tagSize);
347	    CHK_PRT_RET(
348	        sRet != EOK, HCCL_ERROR("%s call strncpy_s failed, tag:%s, tagSize:%u, sRet:%d.", __func__, tag, tagSize, sRet),
349	        HCCL_E_MEMORY);
350	    HCCL_INFO(
351	        "[%s]HcclDfxOpInfo param: algTag[%s], opMode[%u], opType[%u], reduceOp[%u], dataType[%u], dataCount[%llu], "
352	        "root[%u], engine[%s], inputMemAddr[0x%llx], inputMemSize[%llu], outputMemAddr[0x%llx], outputMemSize[%llu], "
353	        "cpuTsThread[0x%llu], cpuWaitAicpuNotifyIdx[%u]",
354	        __func__, hcclDfxOpInfo.algTag, hcclDfxOpInfo.opMode, hcclDfxOpInfo.opType, hcclDfxOpInfo.reduceOp,
355	        hcclDfxOpInfo.dataType, hcclDfxOpInfo.dataCount, hcclDfxOpInfo.root,
356	        GetEnumToString(GetCommEngineStatusStrMap(), hcclDfxOpInfo.engine).c_str(), hcclDfxOpInfo.inputMemAddr,
357	        hcclDfxOpInfo.inputMemSize, hcclDfxOpInfo.outputMemAddr, hcclDfxOpInfo.outputMemSize, hcclDfxOpInfo.cpuTsThread,
358	        hcclDfxOpInfo.cpuWaitAicpuNotifyIdx);
359	    return HCCL_SUCCESS;
360	}
